            this.version = '1.1.0';

            this.CUSTOMERS = [
                { id: 1,  name: 'RefiCosta',              country: 'Costa Rica', capacity: 250, segment: 2, eve: 3950, vbp: 'high', proc: 'aggressive', round: 1 },
                { id: 2,  name: 'PetroBahía',             country: 'Brazil',     capacity: 180, segment: 1, eve: 3200, vbp: 'low',  proc: 'aggressive', round: 2 },
                { id: 3,  name: 'Andina Refining',        country: 'Peru',       capacity: 120, segment: 4, eve: 1200, vbp: 'high', proc: 'moderate',   round: 2 },
                { id: 4,  name: 'CentroAmericana Energy', country: 'Honduras',   capacity:  80, segment: 3, eve:  800, vbp: 'low',  proc: 'moderate',   round: 2 },
                { id: 5,  name: 'Magallanes Petrochem',   country: 'Chile',      capacity: 220, segment: 2, eve: 3600, vbp: 'high', proc: 'moderate',   round: 2 },
                { id: 6,  name: 'Yucateca Crude',         country: 'Mexico',     capacity:  90, segment: 3, eve:  900, vbp: 'low',  proc: 'moderate',   round: 3 },
                { id: 7,  name: 'Patagonia Refining',     country: 'Argentina',  capacity: 150, segment: 4, eve: 1400, vbp: 'high', proc: 'low',        round: 3 },
                { id: 8,  name: 'Bolívar Energy',         country: 'Venezuela',  capacity: 140, segment: 1, eve: 2800, vbp: 'low',  proc: 'aggressive', round: 3 },
                { id: 9,  name: 'Caribe Petrochem',       country: 'Trinidad',   capacity: 100, segment: 4, eve: 1100, vbp: 'high', proc: 'low',        round: 3 },
                { id: 10, name: 'Llanos Crude',           country: 'Colombia',   capacity: 110, segment: 3, eve:  950, vbp: 'low',  proc: 'moderate',   round: 3 },
                { id: 11, name: 'Atlántico Refining',     country: 'Uruguay',    capacity:  70, segment: 3, eve:  700, vbp: 'low',  proc: 'low',        round: 3 },
                { id: 12, name: 'Pacífico Energy',        country: 'Ecuador',    capacity: 130, segment: 1, eve: 2500, vbp: 'low',  proc: 'aggressive', round: 3 }
            ];

            this.STRUCTURE_INFO = {
                A: { name: 'Conservative Fixed', target: 0.20 },
                B: { name: 'Premium Fixed',      target: 0.40 },
                C: { name: 'Outcome-Based',      target: 0.55 }
            };

            this.SEGMENT_FIT = {
                1: { A: 0.60, B: 1.00, C: 0.30 },
                2: { A: 0.45, B: 0.85, C: 1.00 },
                3: { A: 1.00, B: 0.65, C: 0.25 },
                4: { A: 0.85, B: 1.00, C: 0.55 }
            };

            this.RESPONSE_INFO = {
                walk:        { signProb: 0.20, discountFactor: 0.00, disciplineDelta:  5, termsBonus: 0 },
                hold_terms:  { signProb: 0.78, discountFactor: 0.00, disciplineDelta:  3, termsBonus: 1 },
                discount_10: { signProb: 0.90, discountFactor: 0.10, disciplineDelta: -1, termsBonus: 0 },
                discount_25: { signProb: 0.97, discountFactor: 0.25, disciplineDelta: -5, termsBonus: 0 }
            };

            this.PROC_THRESHOLD = {
                aggressive: 0.55,
                moderate:   0.45,
                low:        0.35
            };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cumulativeNPV: 0,
                    dealsClosed: 0,
                    dealsLost: 0,
                    cumulativeRevenue: 0,
                    cumulativeEVE: 0,
                    disciplineScore: 70,
                    npvHistory: [],
                    captureHistory: [],
                    disciplineHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    structure: 'B',
                    listPrice: 1800,
                    response: 'hold_terms'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const structureSelect = document.getElementById('structureSelect');
            const priceInput      = document.getElementById('listPriceInput');
            const responseSelect  = document.getElementById('responseSelect');

            if (structureSelect) decisions.structure = structureSelect.value;
            if (priceInput)      decisions.listPrice = parseFloat(priceInput.value);
            if (responseSelect)  decisions.response  = responseSelect.value;

            if (!decisions.structure || !['A','B','C'].includes(decisions.structure)) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warning_structure'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.listPrice) || decisions.listPrice < 100 || decisions.listPrice > 10000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warning_price'), 'warning'
                );
                return false;
            }
            if (!decisions.response) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('warning_response'), 'warning'
                );
                return false;
            }
            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const idx = Math.min((state.currentPeriod || 1) - 1, this.CUSTOMERS.length - 1);
            const customer = this.CUSTOMERS[idx];

            const structInfo = this.STRUCTURE_INFO[d.structure];
            const respInfo   = this.RESPONSE_INFO[d.response];
            const segFit     = this.SEGMENT_FIT[customer.segment][d.structure];

            const priceRatio  = d.listPrice / customer.eve;
            const targetRatio = structInfo.target;
            let priceFit;
            if (priceRatio <= targetRatio) {
                priceFit = 1.0;
            } else {
                const over = (priceRatio - targetRatio) / targetRatio;
                priceFit = Math.max(0.10, 1 - over * 0.95);
            }

            const disciplineBonus = (state.domainState.disciplineScore - 50) / 250;

            const signProb = Math.min(0.99, Math.max(0,
                respInfo.signProb * segFit * priceFit + disciplineBonus
            ));

            const threshold = this.PROC_THRESHOLD[customer.proc];
            const signed = signProb >= threshold;

            const realizedPriceK = signed ? d.listPrice * (1 - respInfo.discountFactor) : 0;
            const contractYears = 3 + respInfo.termsBonus;

            const discountRate = 0.10;
            const yearsCovered = Math.min(5, contractYears);
            let pvFactor = 0;
            for (let y = 1; y <= yearsCovered; y++) {
                pvFactor += 1 / Math.pow(1 + discountRate, y);
            }
            const dealNPV = realizedPriceK * pvFactor;

            const valueCaptureRatio = signed ? (realizedPriceK / customer.eve) : 0;

            state.domainState.cumulativeNPV     += dealNPV;
            state.domainState.cumulativeEVE     += customer.eve;
            state.domainState.cumulativeRevenue += realizedPriceK;
            if (signed) state.domainState.dealsClosed += 1;
            else        state.domainState.dealsLost   += 1;

            state.domainState.disciplineScore = Math.max(0, Math.min(100,
                state.domainState.disciplineScore + respInfo.disciplineDelta
            ));

            state.domainState.npvHistory.push(Math.round(dealNPV));
            state.domainState.captureHistory.push(Math.round(valueCaptureRatio * 100));
            state.domainState.disciplineHistory.push(Math.round(state.domainState.disciplineScore));

            // v1.1.0 FIX: persist a normalized 0-100 score so the instructor results panel
            // (results_utils.php express_resolveDomainScore -> domainState.performance.
            // overallScore) shows a real score instead of "-". Additive; deal math unchanged.
            state.domainState.performance = {
                overallScore: this._computeScore(state.domainState),
                totalNPV: Math.round(state.domainState.cumulativeNPV),
                finalDiscipline: Math.round(state.domainState.disciplineScore)
            };

            const self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({
                    currentPeriod: __eqilNext,
                    domainState: state.domainState
                });
            })((state.currentPeriod || 1) + 1), 500);

            return {
                period: state.currentPeriod,
                customerName: customer.name,
                segment: customer.segment,
                structure: d.structure,
                listPrice: Math.round(d.listPrice),
                response: d.response,
                realizedPrice: Math.round(realizedPriceK),
                signed: signed,
                signProb: Math.round(signProb * 100),
                dealNPV: Math.round(dealNPV),
                valueCaptureRatio: Math.round(valueCaptureRatio * 100),
                contractYears: contractYears,
                disciplineScore: Math.round(state.domainState.disciplineScore)
            };
        }

        _computeScore(ds) {
            // Composite 0-100 aligned with the VBP performance tiers:
            // cumulative NPV 40, avg value capture 30, pricing discipline 20, close rate 10.
            var npv = ds.cumulativeNPV || 0;
            var closed = ds.dealsClosed || 0;
            var capSum = (ds.captureHistory || []).reduce(function(a, b) { return a + b; }, 0);
            var avgCap = closed > 0 ? (capSum / closed) : 0;
            var disc = ds.disciplineScore || 0;
            var attempts = closed + (ds.dealsLost || 0);
            var npvNorm = Math.max(0, Math.min(1, npv / 48000));
            var capNorm = Math.max(0, Math.min(1, avgCap / 50));
            var discNorm = Math.max(0, Math.min(1, disc / 100));
            var closeRate = attempts > 0 ? (closed / attempts) : 0;
            var raw = (npvNorm * 40) + (capNorm * 30) + (discNorm * 20) + (closeRate * 10);
            return Math.round(Math.max(0, Math.min(100, raw)));
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('npvDisplay', 'domainState.cumulativeNPV',
                (v) => '$' + Math.round(v).toLocaleString() + 'K');
            uiManager.bind('dealsClosedDisplay', 'domainState.dealsClosed');
            uiManager.bind('dealsLostDisplay', 'domainState.dealsLost');
            uiManager.bind('disciplineDisplay', 'domainState.disciplineScore',
                (v) => Math.round(v) + ' / 100');
            uiManager.bind('captureDisplay', 'domainState.cumulativeRevenue',
                (v) => {
                    const eve = window.mySimulation.state.domainState.cumulativeEVE || 0;
                    if (eve <= 0) return '0%';
                    return Math.round((v / eve) * 100) + '%';
                });
        }

