        getChartData(state) {
            const labels = state.domainState.npvHistory.map((_, i) => 'D' + (i + 1));
            return {
                npvChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.npvHistory }]
                },
                captureChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.captureHistory },
                        { data: state.domainState.disciplineHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const totalNPV   = history.reduce((s, r) => s + (r.results && r.results.dealNPV ? r.results.dealNPV : 0), 0);
            const closed     = history.filter(r => r.results && r.results.signed).length;
            const lost       = history.length - closed;
            const captureSum = history.reduce((s, r) => s + (r.results && r.results.valueCaptureRatio ? r.results.valueCaptureRatio : 0), 0);
            const avgCapture = closed > 0 ? captureSum / closed : 0;
            const lastResults = history[history.length - 1].results || {};
            const finalDisc  = lastResults.disciplineScore || 0;

            const t = (window.mySimulation && window.mySimulation.t)
                ? (k) => window.mySimulation.t(k) : (k) => k;

            let performance = t('rating_costplus');
            if (totalNPV > 25000 && avgCapture > 25 && finalDisc > 60) performance = t('rating_practitioner');
            if (totalNPV > 35000 && avgCapture > 35 && finalDisc > 75) performance = t('rating_champion');
            if (totalNPV > 45000 && avgCapture > 40 && finalDisc > 80) performance = t('rating_bestinclass');

            const insights = [];
            if (avgCapture < 20) insights.push(t('insight_low_capture'));
            if (finalDisc < 50) insights.push(t('insight_disc_eroded'));
            if (lost > 4) insights.push(t('insight_many_lost'));
            if (closed >= 10 && avgCapture >= 35) insights.push(t('insight_strong'));
            if (!insights.length) insights.push(t('insight_solid'));
            insights.push(t('insight_recall'));

            return {
                overallScore: this._computeScore(window.mySimulation.state.domainState),
                totalNPV: Math.round(totalNPV),
                avgCapture: Math.round(avgCapture),
                dealsClosed: closed,
                dealsLost: lost,
                finalDiscipline: Math.round(finalDisc),
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (!results.signed) return window.mySimulation.t('hint_lost');
            if (results.valueCaptureRatio < 15) return window.mySimulation.t('hint_underprice');
            if (results.response === 'discount_25') return window.mySimulation.t('hint_caved');
            if (state.domainState.disciplineScore < 40) return window.mySimulation.t('hint_disc_low');
            if (results.response === 'hold_terms' && results.signed) return window.mySimulation.t('hint_disciplined');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.customerName',      label: 'Customer', i18nKey: 'col_customer' },
                { key: 'results.segment',           label: 'Seg',      i18nKey: 'col_segment',  formatter: (v) => 'S' + v },
                { key: 'results.structure',         label: 'Struct',   i18nKey: 'col_struct' },
                { key: 'results.listPrice',         label: 'List $K',  i18nKey: 'col_list',     formatter: (v) => '$' + Number(v).toLocaleString() + 'K' },
                { key: 'results.realizedPrice',     label: 'Close $K', i18nKey: 'col_close',    formatter: (v) => v ? '$' + Number(v).toLocaleString() + 'K' : '—' },
