        getPresets() { return null; }

        _updateBriefing(state) {
            const period = state.currentPeriod || 1;
            const idx = Math.min(period - 1, this.CUSTOMERS.length - 1);
            const customer = this.CUSTOMERS[idx];
            if (!customer) return;

            const t = (window.mySimulation && window.mySimulation.t)
                ? (k) => window.mySimulation.t(k)
                : (k) => k;

            const roundEl = document.getElementById('roundIndicator');
            if (roundEl) {
                let key = 'round_3_label';
                if (customer.round === 1) key = 'round_1_label';
                else if (customer.round === 2) key = 'round_2_label';
                roundEl.textContent = t(key);
            }

            const nameEl = document.getElementById('customerName');
            if (nameEl) nameEl.textContent = customer.name;

            const countryEl = document.getElementById('customerCountry');
            if (countryEl) countryEl.textContent = customer.country + ' · ' + customer.capacity + ' kbpd';

            const segEl = document.getElementById('customerSegment');
            if (segEl) segEl.textContent = 'S' + customer.segment;

            const eveEl = document.getElementById('customerEVE');
            if (eveEl) eveEl.textContent = '$' + customer.eve.toLocaleString() + 'K';

            const vbpEl = document.getElementById('customerVBP');
            if (vbpEl) {
                vbpEl.textContent = customer.vbp === 'high' ? t('vbp_high') : t('vbp_low');
                vbpEl.className = 'vbp-pricing-sim-badge ' +
                    (customer.vbp === 'high' ? 'vbp-pricing-sim-badge-good' : 'vbp-pricing-sim-badge-warn');
            }

            const procEl = document.getElementById('customerProc');
            if (procEl) {
                procEl.textContent = t('proc_' + customer.proc);
                let cls = 'vbp-pricing-sim-badge-warn';
                if (customer.proc === 'aggressive') cls = 'vbp-pricing-sim-badge-bad';
                else if (customer.proc === 'low') cls = 'vbp-pricing-sim-badge-good';
                procEl.className = 'vbp-pricing-sim-badge ' + cls;
            }

            const ev = customer.eve;
            const wfEl = document.getElementById('eveWaterfall');
            if (wfEl) {
                const downtime    = Math.round(ev * 0.71);
                const equipLife   = Math.round(ev * 0.14);
                const labor       = Math.round(ev * 0.06);
                const insurance   = Math.round(ev * 0.04);
                const grossDiff   = downtime + equipLife + labor + insurance;
                const integration = Math.round(ev * 0.05);
                const training    = Math.round(ev * 0.03);
                const dataq       = Math.round(ev * 0.05);
                const netDiff     = grossDiff - integration - training - dataq;

                wfEl.innerHTML =
                    '<div class="vbp-pricing-sim-wf-row"><span>' + t('wf_downtime')    + '</span><span>+ $' + downtime.toLocaleString()    + 'K</span></div>' +
                    '<div class="vbp-pricing-sim-wf-row"><span>' + t('wf_equip')       + '</span><span>+ $' + equipLife.toLocaleString()   + 'K</span></div>' +
                    '<div class="vbp-pricing-sim-wf-row"><span>' + t('wf_labor')       + '</span><span>+ $' + labor.toLocaleString()       + 'K</span></div>' +
                    '<div class="vbp-pricing-sim-wf-row"><span>' + t('wf_insurance')   + '</span><span>+ $' + insurance.toLocaleString()   + 'K</span></div>' +
                    '<div class="vbp-pricing-sim-wf-row vbp-pricing-sim-wf-sub"><span>' + t('wf_gross') + '</span><span>$' + grossDiff.toLocaleString() + 'K</span></div>' +
                    '<div class="vbp-pricing-sim-wf-row"><span>' + t('wf_integration') + '</span><span>− $' + integration.toLocaleString() + 'K</span></div>' +
                    '<div class="vbp-pricing-sim-wf-row"><span>' + t('wf_training')    + '</span><span>− $' + training.toLocaleString()    + 'K</span></div>' +
                    '<div class="vbp-pricing-sim-wf-row"><span>' + t('wf_dataq')       + '</span><span>− $' + dataq.toLocaleString()       + 'K</span></div>' +
                    '<div class="vbp-pricing-sim-wf-row vbp-pricing-sim-wf-total"><span>' + t('wf_eve') + '</span><span>$' + netDiff.toLocaleString() + 'K</span></div>';
            }

            const narrEl = document.getElementById('customerNarrative');
            if (narrEl) {
                narrEl.innerHTML = t('briefing_' + customer.id);
            }
        }

        formatCompletionMessage(summary) {
            var t = (window.mySimulation && window.mySimulation.t)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            summary = summary || {};
            var score = (summary.overallScore != null) ? summary.overallScore : null;
            var npv = (summary.totalNPV != null) ? summary.totalNPV : 0;
            var cap = (summary.avgCapture != null) ? summary.avgCapture : 0;
            var closed = (summary.dealsClosed != null) ? summary.dealsClosed : 0;
            var lost = (summary.dealsLost != null) ? summary.dealsLost : 0;
            var disc = (summary.finalDiscipline != null) ? summary.finalDiscipline : 0;
            var rating = summary.performance || '';
            var insights = Array.isArray(summary.insights) ? summary.insights : [];
            var items = insights.map(function(s) { return '<li>' + s + '</li>'; }).join('');
            var scoreBlock = (score != null)
                ? '<div class="vbp-completion-score"><span class="acs-num">' + score
                    + '</span><span class="acs-max">/100</span><div class="acs-cap">'
                    + t('complete_score') + '</div></div>'
                : '';
            return ''
                + '<div class="vbp-completion">'
                +   '<h3 class="vbp-completion-title">' + t('complete_title') + '</h3>'
                +   scoreBlock
                +   '<div class="vbp-completion-kpis">'
                +     '<div class="ack"><div class="ack-label">' + t('complete_npv')
                +       '</div><div class="ack-value">$' + Math.round(npv).toLocaleString() + 'K</div></div>'
                +     '<div class="ack"><div class="ack-label">' + t('complete_capture')
                +       '</div><div class="ack-value">' + cap + '%</div></div>'
                +     '<div class="ack"><div class="ack-label">' + t('complete_closed')
                +       '</div><div class="ack-value">' + closed + ' / ' + (closed + lost) + '</div></div>'
                +     '<div class="ack"><div class="ack-label">' + t('complete_discipline')
                +       '</div><div class="ack-value">' + disc + ' / 100</div></div>'
                +   '</div>'
                +   (rating ? '<p class="vbp-completion-rating"><strong>' + t('complete_rating')
                        + ':</strong> ' + rating + '</p>' : '')
                +   (items ? '<div class="vbp-completion-takeaways"><h4>' + t('complete_takeaways')
                        + '</h4><ul>' + items + '</ul></div>' : '')
                +   '<p class="vbp-completion-thanks">' + t('complete_thanks') + '</p>'
                + '</div>';
        }

